windowclass.script:
function onInit()
	if super and super.onInit then
		super.onInit();
	end
	if Session.IsHost then
		if User.getRulesetName() == "5E" then
			registerMenuItem(Interface.getString("menu_rest"), "restmenu", 7);
			registerMenuItem(Interface.getString("menu_restshort"), "rest_short", 7, 8);
			registerMenuItem(Interface.getString("menu_restlong"), "rest_long", 7, 6);
		end

		if StringManager.contains(Extension.getExtensions(), "ExtendedRest") then
			registerMenuItem(Interface.getString("menu_restextended"), "rest_extended", 7, 2);
		elseif PowerManagerKw then
			registerMenuItem(Interface.getString("menu_restextended"), "rest_extended", 7, 2);
		end
	end
end

function onInit()
	if super and super.onInit then
		super.onInit();
	end
	if OptionsManager and OptionsManager.isOption then
		self.changeHealthDisplay();
		OptionsManager.registerCallback("HPDM", self.changeHealthDisplay);
	end
end
function onClose()
	if OptionsManager and OptionsManager.unregisterCallback then
		OptionsManager.unregisterCallback("HPDM", self.changeHealthDisplay);
	end
	if super and super.onClose then
		super.onClose();
	end
end
function changeHealthDisplay()
	if not label_wounds then
		return;
	end
	-- "" is the Life Ledger default (Wounds); "current" shows remaining HP.
	if OptionsManager.isOption("HPDM", "current") then
		label_wounds.setValue(Interface.getString("ct_label_current"));
		label_wounds.setTooltipText(Interface.getString("ct_tooltip_current"));
	else
		label_wounds.setValue(Interface.getString("ct_label_wounds"));
		label_wounds.setTooltipText(Interface.getString("ct_tooltip_wounds"));
	end
end

function onInit()
	if super and super.onInit then
		super.onInit();
	end
	if OptionsManager and OptionsManager.isOption then
		self.changeHealthDisplay();
		OptionsManager.registerCallback("HPDM", self.changeHealthDisplay);
	end
end
function onClose()
	if OptionsManager and OptionsManager.unregisterCallback then
		OptionsManager.unregisterCallback("HPDM", self.changeHealthDisplay);
	end
	if super and super.onClose then
		super.onClose();
	end
end
function changeHealthDisplay()
	if not label_wounds then
		return;
	end
	if OptionsManager.isOption("HPDM", "current") then
		label_wounds.setValue(Interface.getString("ct_label_current"));
		label_wounds.setTooltipText(Interface.getString("ct_tooltip_current"));
	else
		label_wounds.setValue(Interface.getString("ct_label_wounds"));
		label_wounds.setTooltipText(Interface.getString("ct_tooltip_wounds"));
	end
end

function onInit()
	if super and super.onInit then
		super.onInit();
	end
	if windowlist then
		if not windowlist.isReadOnly() then
			registerMenuItem(Interface.getString("power_menu_action_add"), "radial_create_action", 3);
			registerMenuItem(Interface.getString("list_menu_deleteconfirm"), "radial_delete_action_confirm", 6, 7);

			registerMenuItem(Interface.getString("power_menu_action_reparse"), "radial_reparse_spell", 4);
		end
	end
end

function onInit()
	if super and super.onInit then
		super.onInit();
	end
	registerMenuItem(Interface.getString("power_menu_actiondelete"), "radial_delete_action", 4);
	registerMenuItem(Interface.getString("list_menu_deleteconfirm"), "radial_delete_action_confirm", 4, 3);
end
